import{_ as r,c as a,o as l,ae as i}from"./chunks/framework.CXj_Gucb.js";const o="/oe-user-guide/assets/app-centre-pic.CxCbHrFK.jpg",e="/oe-user-guide/assets/image-filter.CaQ0VzLI.png",s="/oe-user-guide/assets/pic-detail.B_B8fLU4.png",d="/oe-user-guide/assets/pic-info.CBEOUb0P.png",n="/oe-user-guide/assets/add-close.BUfVzSQq.png",h="/oe-user-guide/assets/action.BULdnwvx.png",f=JSON.parse('{"title":"图片AI预警类","description":"","frontmatter":{},"headers":[],"relativePath":"pic.md","filePath":"pic.md","lastUpdated":1766459798000}'),g={name:"pic.md"};function u(c,t,b,p,_,q){return l(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="图片ai预警类" tabindex="-1">图片AI预警类 <a class="header-anchor" href="#图片ai预警类" aria-label="Permalink to &quot;图片AI预警类&quot;">​</a></h1><p><strong>版本：1.0</strong><br><strong>发布日期：2026年01月01日</strong><br><strong>适用对象：预警接收人、行动项责任人、片区质量/EHS代表、合规委员</strong></p><h2 id="一、角色说明" tabindex="-1">一、角色说明 <a class="header-anchor" href="#一、角色说明" aria-label="Permalink to &quot;一、角色说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>权限范围</th><th>操作入口</th></tr></thead><tbody><tr><td><strong>预警项/行动项接收人</strong></td><td>仅处理分配给自己的任务<br>• 无【应用中心】权限</td><td>首页 → 【待确认预警项】<br>首页 → 【待完成行动项】</td></tr><tr><td><strong>应用负责人</strong><br>（片区质量/EHS代表、合规委员）</td><td>可检索本片区全部预警<br>• 可导出、分析数据</td><td>【预警应用中心】→ 各子应用</td></tr></tbody></table><h2 id="二、操作指引" tabindex="-1">二、操作指引 <a class="header-anchor" href="#二、操作指引" aria-label="Permalink to &quot;二、操作指引&quot;">​</a></h2><h3 id="_2-1-功能概述" tabindex="-1">2.1 功能概述 <a class="header-anchor" href="#_2-1-功能概述" aria-label="Permalink to &quot;2.1 功能概述&quot;">​</a></h3><p>系统自动从业务系统获取图像样本，AI 模型将识别以下风险：</p><ul><li>图片上传超时（如 &gt;72 小时）</li><li>关键工步执行异常（如温度贴变红、硅胶涂抹存在断点等）</li><li>图片质量过低或无法识别</li></ul><h3 id="_2-2-适用业务" tabindex="-1">2.2 适用业务 <a class="header-anchor" href="#_2-2-适用业务" aria-label="Permalink to &quot;2.2 适用业务&quot;">​</a></h3><table tabindex="0"><thead><tr><th>业务域</th><th>应用名称</th></tr></thead><tbody><tr><td><strong>大现场质量</strong></td><td>图片 AI-CTQ 检测</td></tr><tr><td><strong>大现场 EHS</strong></td><td>图片 AI-CTS 检测</td></tr><tr><td><strong>制造部</strong></td><td>图片 AI-CTQ 检测</td></tr></tbody></table><h3 id="_2-3-主界面" tabindex="-1">2.3 主界面 <a class="header-anchor" href="#_2-3-主界面" aria-label="Permalink to &quot;2.3 主界面&quot;">​</a></h3><p>进入路径：【预警应用中心】 → 【图片AI检测应用】</p><p><img src="'+o+'" alt="图片类主列表页"></p><h3 id="_2-4-筛选与查询" tabindex="-1">2.4 筛选与查询 <a class="header-anchor" href="#_2-4-筛选与查询" aria-label="Permalink to &quot;2.4 筛选与查询&quot;">​</a></h3><p>支持按以下条件筛选：</p><ul><li>预警项编号、时间、状态</li><li>工步上传时间、所属大区、工单号、工步描述、项目编码</li><li>AI 监测模型（如“温度贴”）等</li></ul><p><img src="'+e+'" alt="图片类筛选区"></p><h3 id="_2-5-预警详情与复核" tabindex="-1">2.5 预警详情与复核 <a class="header-anchor" href="#_2-5-预警详情与复核" aria-label="Permalink to &quot;2.5 预警详情与复核&quot;">​</a></h3><ul><li>点击右侧的【查看】按钮，进入详情页：<br></li></ul><p><img src="'+s+'" alt="查看详情页"></p><ul><li>在详情页中，查看 AI 预警结果、工单信息；点击【查看】按钮，可预览对应图片：<br></li></ul><p><img src="'+d+'" alt="查看详情页"></p><ul><li>在【确认信息】区域： <ul><li>选择 <strong>是否问题</strong>（是 / 否）</li><li>填写 <strong>确认描述</strong>（必填）</li></ul></li></ul><blockquote><p>✅ 当选择“是”时，系统将显示【处理信息】区域，提供以下三种处理方式：</p></blockquote><h4 id="处理方式一-等待处理" tabindex="-1">处理方式一：等待处理 <a class="header-anchor" href="#处理方式一-等待处理" aria-label="Permalink to &quot;处理方式一：等待处理&quot;">​</a></h4><ul><li><strong>适用场景</strong>：问题已识别，但暂不立即整改（如需排产、等待备件、计划性维护等）</li><li><strong>操作步骤</strong>： <ul><li>在“处理方式”下拉框中选择 <strong>“等待处理”</strong></li><li>可选：在“确认描述“中说明具体情况</li></ul></li><li><strong>系统行为</strong>： <ul><li>预警状态更新为 <strong>“已复核”</strong></li><li>不生成行动项</li><li>保留在预警记录中，供后续跟踪</li></ul></li></ul><h4 id="处理方式二-补充信息关闭" tabindex="-1">处理方式二：补充信息关闭 <a class="header-anchor" href="#处理方式二-补充信息关闭" aria-label="Permalink to &quot;处理方式二：补充信息关闭&quot;">​</a></h4><ul><li><strong>适用场景</strong>：问题已解决、无需进一步动作，或属于可接受偏差</li><li><strong>操作步骤</strong>： <ul><li>选择 <strong>“补充信息关闭”</strong></li><li>填写补充信息</li><li>建议上传证据文件（如整改前后对比图、系统截图等）</li></ul></li><li><strong>系统行为</strong>： <ul><li>预警状态变更为 <strong>“已关闭”</strong></li><li>不创建行动项</li><li>计入“有效预警-已闭环”统计，用于质量分析</li></ul></li></ul><p><img src="'+n+'" alt="补充信息关闭"></p><h4 id="处理方式三-添加行动项" tabindex="-1">处理方式三：添加行动项 <a class="header-anchor" href="#处理方式三-添加行动项" aria-label="Permalink to &quot;处理方式三：添加行动项&quot;">​</a></h4><ul><li><strong>适用场景</strong>：需明确责任人、整改措施和完成时限（如返工、维修、流程优化等）</li><li><strong>操作步骤</strong>： <ul><li>选择 <strong>“添加行动项”</strong></li><li>填写行动项相关信息</li></ul></li><li><strong>系统行为</strong>： <ul><li>自动生成一条 <strong>【待闭环行动项】</strong></li><li>自动分配至当前用户（或可指定其他责任人）</li><li>推送通知至责任人首页</li><li>行动项状态独立跟踪，支持上传整改证据与审核闭环</li></ul></li></ul><p><img src="'+h+'" alt="添加行动项"></p><blockquote><p>📌 <strong>注意事项</strong>：</p><ul><li>“附件”支持多文件上传（JPG、PNG、PDF、DOCX 等），单文件 ≤20MB</li><li>所有提交内容（包括处理方式、描述、附件）均永久留痕，支持审计追溯</li><li>一旦提交，处理方式不可更改；如需调整，请联系应用负责人发起修改流程</li></ul></blockquote><hr><h3 id="示例场景对照表" tabindex="-1">示例场景对照表 <a class="header-anchor" href="#示例场景对照表" aria-label="Permalink to &quot;示例场景对照表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>实际场景</th><th>推荐处理方式</th><th>说明</th></tr></thead><tbody><tr><td>图片模糊但作业无异常，已重新上传</td><td>补充信息关闭</td><td>快速闭环</td></tr><tr><td>发现硅胶涂抹断点，需返工</td><td>添加行动项</td><td>创建任务，指派工程师处理</td></tr><tr><td>温度贴变红，但设备正在计划检修中</td><td>等待处理</td><td>说明检修情况</td></tr></tbody></table><blockquote><p>🔍 <strong>通用说明</strong>：<br> 上述三种处理方式适用于 <strong>图片类、文档类、APQP类</strong> 所有预警类型，确保问题响应路径灵活、合规、可追踪。</p></blockquote><h2 id="三、操作路径对照表" tabindex="-1">三、操作路径对照表 <a class="header-anchor" href="#三、操作路径对照表" aria-label="Permalink to &quot;三、操作路径对照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>预警/行动项接收人</th><th>应用负责人</th></tr></thead><tbody><tr><td>复核预警</td><td>首页 →【待确认预警项】</td><td>应用中心 → 各子应用 → 查看预警项</td></tr><tr><td>闭环行动项</td><td>首页 →【待闭环行动项】</td><td>应用中心 → 各子应用 → 查看行动项</td></tr><tr><td>导出数据</td><td>❌ 不支持</td><td>✅ 支持（Excel、CSV）</td></tr><tr><td>全局检索</td><td>❌ 不支持</td><td>✅ 按片区/项目等条件筛选</td></tr></tbody></table><h2 id="四、常见问题-faq" tabindex="-1">四、常见问题（FAQ） <a class="header-anchor" href="#四、常见问题-faq" aria-label="Permalink to &quot;四、常见问题（FAQ）&quot;">​</a></h2><p><strong>Q：为什么我在首页看不到某条预警？</strong><br> A：该预警未分配给您。请确认所属工单/项目是否在您的责任范围内。</p><p><strong>Q：应用负责人能否代替接收人复核？</strong><br> A：不建议。系统遵循“谁接收、谁复核”原则，确保责任到人。</p><p><strong>Q：图片类中的“AI-CTS”和“AI-CTQ”有何区别？</strong><br> A：</p><ul><li><strong>CTQ</strong>（Critical to Quality）：聚焦产品质量关键点</li><li><strong>CTS</strong>（Critical to Safety）：聚焦人员/环境安全关键点</li></ul><p><strong>Q：如何申请应用中心权限？</strong><br> A：联系系统管理员，提供角色证明。</p><blockquote><p>🔍 <strong>更多问题</strong>：参见 <a href="/oe-user-guide/faq">FAQ 文档</a></p></blockquote>',46)])])}const k=r(g,[["render",u]]);export{f as __pageData,k as default};
